1	"""
2	Turn the page a worker is on into compact text for the model, with refs for everything it can act on.
3	
4	What a person would see, not the raw DOM: hidden elements are dropped (decoy text and injected instructions are
5	usually `hidden` or `aria-hidden`), collapsed `<details>` are opened, tooltips and canvas/img labels are inlined,
6	same-origin iframes are walked in place and zero-width characters are stripped. Interactive elements get a
7	`data-ar` ref such as `e12` that `locate` resolves again for clicking and filling.
8	"""
9	import asyncio
10	import difflib
11	import re
12	
13	from playwright.async_api import Frame, Locator, Page
14	
15	# A page whose script hangs (an endless loop) never answers an evaluate: every call into a page is bounded, so a
16	# frozen tab costs seconds, not the run.
17	WALK_SECONDS = 20.0
18	FRAME_SECONDS = 5.0
19	DIFF_CHARS = 40000  # longer views are sent whole instead of diffed (difflib is quadratic in the worst case)
20	
21	WALK_JS = r"""
22	([start, stamp]) => {
23	  const ZW = /[​‌‍⁠﻿­]/g;
24	  const clean = s => (s || '').replace(ZW, '').replace(/\s+/g, ' ').trim();
25	  const SKIP = new Set(['SCRIPT', 'STYLE', 'NOSCRIPT', 'TEMPLATE', 'HEAD', 'META', 'LINK']);
26	  const BLOCK = /^(block|flex|grid|table|table-row|list-item|flow-root|table-caption)$/;
27	  const ROLES = new Set(['button', 'link', 'tab', 'menuitem', 'option', 'checkbox', 'radio', 'switch', 'combobox',
28	                         'slider', 'REDACTED', 'searchbox']);
29	  const SELECT_CHARS = 600, SELECT_HEAD = 8, SELECT_TAIL = 2;  // longer option lists are shortened
30	  let n = start;
31	  const out = [];
32	  const crossOrigin = [];
33	  const emit = s => out.push(s);
34	
35	  function isHidden(el, win) {
36	    if (el.hidden || el.getAttribute('aria-hidden') === 'true' || el.inert) return true;
37	    const cs = win.getComputedStyle(el);
38	    return cs.display === 'none' || cs.visibility === 'hidden' || cs.visibility === 'collapse';
39	  }
40	  function textOnly(node) {  // a label's own words, without the controls and styles it wraps
41	    const copy = node.cloneNode(true);
42	    copy.querySelectorAll('select,option,input,textarea,button,style,script').forEach(e => e.remove());
43	    return copy.textContent;
44	  }
45	  function labelOf(el) {
46	    const own = el.getAttribute('aria-label');
47	    if (own) return clean(own);
48	    const by = el.getAttribute('aria-labelledby');
49	    if (by) {
50	      const t = by.split(/\s+/).map(id => el.ownerDocument.getElementById(id)).filter(Boolean)
51	        .map(e => e.textContent).join(' ');
52	      if (clean(t)) return clean(t);
53	    }
54	    if (el.labels && el.labels.length) {
55	      const t = clean(Array.from(el.labels).map(textOnly).join(' '));
56	      if (t) return t;
57	    }
58	    return clean(el.getAttribute('title') || el.getAttribute('placeholder') || el.getAttribute('name') || '');
59	  }
60	  function isInteractive(el) {
61	    const tag = el.tagName;
62	    if (tag === 'A' && el.hasAttribute('href')) return true;
63	    if (tag === 'BUTTON' || tag === 'SELECT' || tag === 'TEXTAREA') return true;
64	    if (tag === 'SUMMARY') return el.hasAttribute('onclick');  // details are always shown open
65	    if (tag === 'INPUT') return el.type !== 'hidden';
66	    const role = el.getAttribute('role');
67	    return !!(role && ROLES.has(role)) || el.hasAttribute('onclick');
68	  }
69	  function ref(el) { const r = 'e' + (n++); el.setAttribute('data-ar', r); return r; }
70	
71	  function describe(el) {
72	    const r = ref(el);
73	    const tag = el.tagName;
74	    const dis = el.disabled ? ' disabled' : '';
75	    if (tag === 'A') {
76	      const name = clean(el.innerText) || labelOf(el);
77	      return `[${r} link "${name}" -> ${el.getAttribute('href')}]`;
78	    }
79	    if (tag === 'SELECT') {
80	      const opts = Array.from(el.options);
81	      const sel = opts.filter(o => o.selected).map(o => clean(o.textContent)).join(', ');
82	      const names = opts.map(o => clean(o.textContent) + (o.disabled ? ' (disabled)' : ''));
83	      let list = names.join(' | ');
84	      if (list.length > SELECT_CHARS && names.length > SELECT_HEAD + SELECT_TAIL + 1) {
85	        // a long list costs tokens on every view; show its shape, options(ref, contains) lists the rest
86	        const hidden = names.length - SELECT_HEAD - SELECT_TAIL;
87	        list = [...names.slice(0, SELECT_HEAD), `... ${hidden} more: options(${r}) ...`,
88	                ...names.slice(-SELECT_TAIL)].join(' | ');
89	        list = `(${names.length}) ${list}`;
90	      }
91	      return `[${r} select "${labelOf(el)}" selected="${sel}"${dis} options: ${list}]`;
92	    }
93	    if (tag === 'TEXTAREA') return `[${r} textarea "${labelOf(el)}" value="${clean(el.value)}"${dis}]`;
94	    if (tag === 'INPUT') {
95	      const t = (el.type || 'text').toLowerCase();
96	      if (t === 'checkbox' || t === 'radio')
97	        return `[${r} ${t} "${labelOf(el)}"${el.checked ? ' checked' : ' unchecked'}${dis}]`;
98	      if (t === 'range')
99	        return `[${r} slider "${labelOf(el)}" value=${el.value} min=${el.min || 0} max=${el.max || 100}${dis}]`;
100	      if (t === 'submit' || t === 'button' || t === 'reset' || t === 'image')
101	        return `[${r} button "${clean(el.value) || labelOf(el)}"${dis}]`;
102	      const kind = t === 'password' ? 'password' : 'REDACTED';
103	      const value = t === 'password' ? (el.value ? '***' : '') : clean(el.value);
104	      const ph = el.placeholder ? ` placeholder="${clean(el.placeholder)}"` : '';
105	      return `[${r} ${kind} "${labelOf(el)}" value="${value}"${ph}${el.required ? ' required' : ''}${dis}]`;
106	    }
107	    const role = el.getAttribute('role') || tag.toLowerCase();
108	    const name = clean(el.innerText) || labelOf(el);
109	    const state = el.getAttribute('aria-expanded') ? ` expanded=${el.getAttribute('aria-expanded')}` : '';
110	    return `[${r} ${role} "${name}"${state}${dis}]`;
111	  }
112	
113	  function walkDoc(doc, win) {
114	    doc.querySelectorAll('[data-ar]').forEach(e => e.removeAttribute('data-ar'));
115	    doc.querySelectorAll('details:not([open])').forEach(d => { d.open = true; });
116	    doc.documentElement.dataset.arWalked = stamp;
117	    if (doc.body) walk(doc.body, win);
118	  }
119	
120	  function walk(node, win) {
121	    for (const child of node.childNodes) {
122	      if (child.nodeType === 3) {
123	        const raw = child.nodeValue.replace(ZW, '');
124	        const pre = /^pre/.test(win.getComputedStyle(node).whiteSpace);  // keep the lines of files and tables
125	        const t = pre ? raw.replace(/[ \t]+/g, ' ').replace(/\n/g, '\u2028') : raw.replace(/\s+/g, ' ');
126	        if (t.trim()) emit(t);
127	        continue;
128	      }
129	      if (child.nodeType !== 1) continue;
130	      const el = child;
131	      if (SKIP.has(el.tagName)) continue;
132	      const role = el.getAttribute('role');
133	      if (role === 'tooltip') {
134	        if (!el.hidden && el.getAttribute('aria-hidden') !== 'true') emit(` (tooltip: ${clean(el.textContent)}) `);
135	        continue;
136	      }
137	      if (isHidden(el, win)) continue;
138	      const tag = el.tagName;
139	      if (tag === 'CANVAS' || tag === 'IMG' || tag === 'svg' || tag === 'SVG' || role === 'img') {
140	        const label = clean(el.getAttribute('aria-label') || el.getAttribute('alt') || el.getAttribute('title'));
141	        if (label) emit(` [img: ${label}] `);
142	        continue;
143	      }
144	      if (tag === 'IFRAME' || tag === 'FRAME') {
145	        const src = el.getAttribute('src') || '';
146	        let inner = null;
147	        try { inner = el.contentDocument; } catch (e) { inner = null; }
148	        if (inner && inner.body) {
149	          emit(`\n[frame ${src}]\n`);
150	          walkDoc(inner, el.contentWindow);
151	          emit(`\n[/frame]\n`);
152	        } else {
153	          crossOrigin.push(src);
154	          emit(`\n[frame ${src} (separate)]\n`);
155	        }
156	        continue;
157	      }
158	      const cs = win.getComputedStyle(el);
159	      const block = BLOCK.test(cs.display) || /^H[1-6]$/.test(tag) || tag === 'BR';
160	      if (block) emit('\n');
161	      if (/^H[1-6]$/.test(tag)) emit('#'.repeat(+tag[1]) + ' ');
162	      if (cs.display === 'list-item') emit('- ');
163	      if (isInteractive(el)) {
164	        emit(' ' + describe(el) + ' ');
165	        // a label or summary may wrap further controls; walk those, not the text again
166	        el.querySelectorAll('input,select,textarea,button').forEach(inner => {
167	          if (inner !== el && !isHidden(inner, win)) emit(' ' + describe(inner) + ' ');
168	        });
169	      } else {
170	        walk(el, win);
171	        if (tag === 'TIME' && el.getAttribute('datetime')) emit(` (datetime=${el.getAttribute('datetime')})`);
172	        const title = el.getAttribute('title');
173	        if (title && !clean(el.textContent).includes(clean(title))) emit(` (title: ${clean(title)})`);
174	      }
175	      if (cs.display === 'table-cell') emit(' | ');
176	      if (block) emit('\n');
177	    }
178	  }
179	
180	  walkDoc(document, window);
181	  const text = out.join('')
182	    .replace(/[ \t]+/g, ' ')
183	    .replace(/ *\n */g, '\n')
184	    .replace(/\n{2,}/g, '\n')
185	    .replace(/\u2028/g, '\n')
186	    .trim();
187	  return {text, next: n, crossOrigin};
188	}
189	"""
190	
191	
192	async def observe(page: Page, stamp: str = "1") -> str:
193	    """The page's visible content as text with `[eN ...]` refs; frames the main walk could not enter follow."""
194	    result = await asyncio.wait_for(page.main_frame.evaluate(WALK_JS, [1, stamp]), WALK_SECONDS)
195	    parts = [result["text"]]
196	    next_id = result["next"]
197	    if result["crossOrigin"]:
198	        for frame in page.frames[1:]:
199	            try:
200	                walked = await asyncio.wait_for(
201	                    frame.evaluate("document.documentElement.dataset.arWalked || ''"), FRAME_SECONDS)
202	                if walked == stamp:
203	                    continue
204	                sub = await asyncio.wait_for(frame.evaluate(WALK_JS, [next_id, stamp]), WALK_SECONDS)
205	            except Exception:
206	                continue
207	            next_id = sub["next"]
208	            parts.append(f"[frame {frame.url}]\n{sub['text']}\n[/frame]")
209	    return "\n".join(parts)
210	
211	
212	async def locate(page: Page, ref: str) -> Locator | None:
213	    """The element a ref from the latest `observe` points at, in whichever frame it lives."""
214	    selector = f'[data-ar="{ref.strip()}"]'
215	    frames: list[Frame] = [page.main_frame, *page.frames[1:]]
216	    for frame in frames:
217	        try:
218	            locator = frame.locator(selector)
219	            if await asyncio.wait_for(locator.count(), FRAME_SECONDS):
220	                return locator.first
221	        except Exception:
222	            continue
223	    return None
224	
225	
226	OPTIONS_JS = r"""
227	(e, contains) => {
228	  const ZW = /[​‌‍⁠﻿­]/g;
229	  const clean = s => (s || '').replace(ZW, '').replace(/\s+/g, ' ').trim();
230	  const want = clean(contains).toLowerCase();
231	  const all = Array.from(e.options || []).map(o => clean(o.textContent) + (o.disabled ? ' (disabled)' : '')
232	                                                  + (o.selected ? ' (selected)' : ''));
233	  return {total: all.length, hits: all.filter(t => t.toLowerCase().includes(want))};
234	}
235	"""
236	
237	
238	async def select_options(page: Page, ref: str, contains: str = "") -> tuple[int, list[str]] | None:
239	    """All options of the select `ref` (or those whose text contains `contains`, ignoring case); None without one."""
240	    element = await locate(page, ref)
241	    if element is None or await asyncio.wait_for(element.evaluate("e => e.tagName"), FRAME_SECONDS) != "SELECT":
242	        return None
243	    found = await asyncio.wait_for(element.evaluate(OPTIONS_JS, contains), WALK_SECONDS)
244	    return found["total"], found["hits"]
245	
246	
247	
248	CONTROL = re.compile(r"(\[e\d+ (?:[^\[\]]|\[[^\[\]]*\])*\])")  # one [eN ...] element, allowing [..] inside
249	
250	
251	def _pieces(view: str) -> list[str]:
252	    """A view cut into lines, and lines into their text and each control, so a changed field is one piece."""
253	    return [piece.strip() for line in view.split("\n") for piece in CONTROL.split(line) if piece.strip()]
254	
255	
256	def changes(old: str, new: str, share: float = 0.4) -> str | None:
257	    """The pieces (text runs and controls) of `new` that differ from `old`, each after the last unchanged one.
258	
259	    Unchanged pieces are identical text, refs included, so together with the old view they give the new page.
260	    None when the change is a large part of the page (then the whole view is clearer and not much longer).
261	    """
262	    if len(old) + len(new) > DIFF_CHARS:
263	        return None
264	    before, after = _pieces(old), _pieces(new)
265	    out = []
266	    for op, i1, i2, j1, j2 in difflib.SequenceMatcher(None, before, after, autojunk=False).get_opcodes():
267	        if op == "equal":
268	            continue
269	        out.append(f"@@ after {before[i1 - 1][:80]!r}:" if i1 else "@@ at the top:")
270	        out += [f"- {piece[:80]}" + ("..." if len(piece) > 80 else "") for piece in before[i1:i2]]
271	        out += [f"+ {piece}" for piece in after[j1:j2]]
272	    text = "\n".join(out)
273	    return text if len(text) <= share * len(new) else None
274

